const tradeRole=renderRole;
renderRole=function(){tradeRole();if(role!=='military')return;const r=regiment();if(!r)return;const units=Military.types;const summary=$('rolePanel').querySelector('.mini-card');if(summary)summary.innerHTML=`<strong>${r.troops} troops · Cell ${r.cell}</strong><div class="unit-strip">${Object.entries(units).map(([k,t])=>`<span>${t.icon} ${r.units[k]} ${t.name}</span>`).join('')}</div><p>Readiness ${r.readiness}% · Carried food ${r.supply.toFixed(1)}<br>🚚 ${esc(r.supplyStatus)}<br>${r.order?'Moving toward cell '+r.order.destination:'Holding position'}</p>`;
const recruit=$('recruit');if(recruit){const label=document.createElement('label');label.className='field';label.innerHTML=`Troops to recruit<select id="recruitType">${options(Object.entries(units).map(([k,t])=>[k,`${t.icon} ${t.name} · ${t.money} money / ${t.metal} metal / ${t.cloth} cloth`]),'infantry')}</select>`;recruit.parentElement.before(label);recruit.textContent='Recruit 10 troops';recruit.onclick=()=>action(()=>Game.recruit(state,regimentId,$('recruitType').value),'10 troops recruited from the local population.');if(state.phase!=='implement')$('recruitType').disabled=true;}
const others=state.regiments.filter(x=>x.id!==r.id&&x.country===active&&x.cell===r.cell&&x.troops>0);const transfer=document.createElement('section');transfer.innerHTML=`<hr><h3>⇄ Assign troops between regiments</h3><p class="role-intro">Both regiments must be in the same cell. Transfers move existing troops; they do not create new ones.</p>${others.length?`${field('Destination regiment','transferTo',others.map(r=>[r.id,r.name]),others[0].id)}${field('Troop type','transferType',Object.entries(units).map(([k,t])=>[k,t.icon+' '+t.name]),'infantry')}<label class="field">Number to transfer<input id="transferCount" type="number" min="1" value="5"></label><button id="transferTroops">Transfer troops</button>`:'<p class="role-intro">Bring two regiments together, or split this one, to transfer troops.</p>'}<h3>🚚 Keep the army supplied</h3><p class="role-intro">A regiment needs a path through friendly or allied cells to one of your settlements or depots, within 8 cells. Enemy regiments block that path. Cut-off armies use carried food, then lose readiness.</p><p class="role-intro">⚔ Battles use skirmish, then melee. All engaged regiments deal damage before losses are applied in each phase. Mountains, home territory and forts help defenders. Allies do not attack each other.</p>`;$('rolePanel').append(transfer);if($('transferTroops'))$('transferTroops').onclick=()=>action(()=>Military.transfer(state,regimentId,Number($('transferTo').value),$('transferType').value,Number($('transferCount').value)),'Troops transferred.');if(state.phase!=='implement')transfer.querySelectorAll('input,select,button').forEach(e=>e.disabled=true);const old=$('rolePanel').querySelector('small');if(old&&old.textContent.includes('Infantry only'))old.textContent='All troop types recruit 10 people. Costs depend on equipment. Set the military allowance in Economy.';};
render();
